self.__next_f.push([1,"<!--<div class="container container--narrow">
 <div class="island slab">
 <p class="h4">
 Sorry, we kunnen u deze pagina niet tonen.
 </p>
 <ul>
 <li>Ga naar de <a href="/">startpagina</a> van limburger.nl</li>
 <li>Zoek het artikel dat u wenst via de <a href="/zoeken/">zoekfunctie in het archief</a> of raadpleeg <a href="/tags">onze tags</a></li>
 </ul>
 </div>
 <h1 class="align-center text-uc h3">404 - pagina niet gevonden</h1>
</div>
<div id="body-for-newsapp" style="display: none;">
 <div style="text-align: center; display: block; margin-top: 3rem; margin-bottom: 0; padding: 1.5rem;">
 <p style="color: #4A4A4A; font-family: 'Roboto', sans-serif !important; font-size: 24px;
 font-weight: bold !important; margin: 1em 0 1em 0 !important">Oei, de link is dood!</p>
 <p style="color: #4A4A4A; font-family: 'Roboto', sans-serif !important; font-size: 14px;
 font-weight: normal !important; margin: 1em 0 5em 0 !important;">Terwijl wij de begrafenis regelen, kan je best teruggaan naar het vorige scherm.</p>
 <img src="https://static.nieuwsblad.be/Assets/Images_Upload/2017/10/03/404-dead.png" style="margin-bottom:0; padding-bottom: 0">
 </div>
 </div>
-->

<script type="application/javascript">
 if (window.location.href.toLowerCase().indexOf('origin=app') > -1) {
 var navTags = document.getElementsByTagName('nav');
 var headerTags = document.getElementsByTagName('header');
 var footerTags = document.getElementsByTagName('footer');
 var htmlTag = document.getElementsByTagName('html')[0];
 var bodyTag = document.getElementsByTagName('body')[0];
 var bodyForW3 = document.getElementById('body-for-w3');
 var bodyForNewsApp = document.getElementById('body-for-newsapp');

 htmlTag.style.fontSize = '100%';
 bodyTag.style.backgroundColor = '#eee';
 bodyTag.style.maxWidth = '100%';
 bodyForW3.style.display = 'none';
 bodyForNewsApp.style.display = 'block';

 for(var i = 0; i < navTags.length; i++) {
 navTags[i].style.display = 'none';
 }
 for(var i = 0; i < headerTags.length; i++) {
 headerTags[i].style.display = 'none';
 }
 for(var i = 0; i < footerTags.length; i++) {
 footerTags[i].style.display = 'none';
 }
 }
 </script>"])

self.__next_f.push([1,"<style>

@import url("https://markup.limburger.nl/extra/static/scripts/foundation/css/foundation.css");
@import url("https://markup.limburger.nl/extra/static/scripts/fontawesome/css/solid.css");

.toosenhenk {-webkit-transform: scaleX(-1); transform: scaleX(-1); margin: 20px 0 -20px 0;}

iframe, .ad-group {display:none!important;}

[data-mht-widget="meest-gelezen"] {position: relative; right: -33.333%;}


/* /// MNT HEADER FIX /// */
.site-subnav-sticky {display: none;}

@media only screen and (max-width: 600px) {
	.site-index, .site-footer {margin:0!important;}
	.temp_newLogoEnabled .site-logo-sticky {
		max-width: 100%;
		position: unset;
		margin-left: 0;
	}

	.site-menu-link {
		color: #fff;
	margin: 8px 4px;
	}

	.comment__footer .site-header-sticky [class*=icon], .site-header-sticky .comment__footer [class*=icon], .site-header-sticky .icon {
		width: 1.5rem;
		height: 1.5rem;
	}
}

/* /// BODY STYLING /// */
h1, h2, h3, h4, h5, h6 {
 font-family: Merriweather,sans-serif;
 font-weight: 900;
	margin: 0 0 1rem;
}

h1 {
 font-size: 2rem;
	margin-bottom: 0.75rem;
}

.head-image {
max-width:100%;
width: 500px;
margin: .5rem auto 2rem;
display: block;
}

.contentbox {
 border-radius: 0.5rem;
 padding: 1.25rem;
 width: 100%;
 max-width: 500px;
 margin: 0 auto;
 margin-bottom: 2rem;
}

.contentbox.white {
	background: #fff;
}

.contentbox.grey {
	background: #f2f2f2;
}

.contentbox.darkblue {
	background: #003d61;
	color:#fff;
}

.contentbox p {
	margin: 0 0 1.25rem;
font-family: var(--header-strong-sm-typography-font-family);
font-size:16px;
line-height:1.4;
}

.contentbox.white.nonsubscriber {
	border-bottom-left-radius: 0;
	border-bottom-right-radius: 0;
}

.contentbox.darkblue.nonsubscriber {
	border-top-left-radius: 0;
	border-top-right-radius: 0;
}

/* /// BUTTONS /// */
.button {
font-family:var(--header-strong-sm-typography-font-family);
 font-size: 1rem; /*display: inline-flex;*/
 cursor: pointer;
 height: auto;
 font-weight: 600;
 padding: 0.625rem 0.85rem 0.625rem;
 border-radius: 5px;
 -webkit-box-shadow: 0px 0px 10px 0px rgba(0,0,0,0.3);
 -moz-box-shadow: 0px 0px 10px 0px rgba(0,0,0,0.3);
 box-shadow: 0px 0px 10px 0px rgba(0,0,0,0.3);
 line-height: 1.25;
}

.button i {
 font-size:.75rem;
}
 .button::before {

 }

 .button.back::before {

 }

 .button > a, .button > a:hover {
 color: #fff;
 }

 .button.small {
 padding: 0.3125rem 0.5rem 0.35rem;
 font-size: 0.875rem !important;
 }

 .button.ghost {
 background:#fff;
 color: #0075bf;
 font-size: 1rem;
 border: 2px solid #0075bf;
 -webkit-box-shadow: none;
 -moz-box-shadow: none;
 box-shadow: none;
 }

 .button.ghost:hover {
 background: #0075bf;
 color: #fff;
 }

 .button.ghost:hover::before {
 color: #0075bf;
 transition: background-color 0.25s ease-out, color 0.25s ease-out;
 }

 .button.blue {
 background: #0075bf;
 border: 1px solid #005e99;
 border-bottom: 4px solid #005e99;
 color:#fff;
 }

 .button.blue:hover {
 background: #005e99;
 border: 1px solid #004f80;
 border-bottom: 4px solid #004f80;
 }

 .button.midblue {
 background: #84cff0;
 border: 1px solid #6faec9;
 border-bottom: 4px solid #6faec9;
 }

 .button.midblue:hover {
 background: #6faec9;
 border: 1px solid #6198b0;
 border-bottom: 4px solid #6198b0;
 }

 .button.green {
 background: #80c917;
 border: 1px solid #40aa28;
 border-bottom: 4px solid #40aa28;
 }

 .button.green:hover {
 background: #009640;
 border: 1px solid #007d36;
 border-bottom: 4px solid #007d36;
 }

	.button.white {
 background: #fff;
		border: 1px solid #005e99;
		border-bottom: 4px solid #005e99;
		color: #005e99;
 }

 .button.white:hover {
 background: #005e99;
 border: 1px solid #004f80;
 border-bottom: 4px solid #004f80;
			color:#fff;
 }
</style>"])

